const {chromium}=require('playwright');const fs=require('fs');(async()=>{let b=await chromium.launch({executablePath:'/usr/bin/google-chrome',headless:true});let out=[];for(let h of ["quanto-custa-servico-dpo-externo-brasil","software-reconhecimento-texto-documentos-digitalizados","solucoes-digitalizacao-documentos-empresariais","cedoc","consultoria-decreto10278-solucao","digitalizacao-documental-curitiba-empresas-recomendadas-contrat","digitalizacao-documental-paulo-empresas-melhor-custo-beneficio","digitalizar-arquivos-solucao","ecm","servicos","arquivardocumento","arquivos-educacao"]){let url='https://'+h+'.arquindex.com.br/'+(h==='ecm'?'custo.html':h==='quanto-custa-servico-dpo-externo-brasil'?'diagnostico.html':'');for(let w of [390,1440]){let p=await b.newPage({viewport:{width:w,height:900}});try{let r=await p.goto(url,{waitUntil:'networkidle',timeout:45000});let d=await p.evaluate(()=>({title:document.title,canonical:[...document.querySelectorAll('link[rel=canonical]')].map(x=>x.href),h1:[...document.querySelectorAll('h1')].map(x=>x.innerText),width:document.documentElement.clientWidth,scroll:document.documentElement.scrollWidth,overflow:[...document.querySelectorAll('body *')].filter(x=>{let r=x.getBoundingClientRect();return r.width&&r.right>innerWidth+1}).slice(0,12).map(x=>({tag:x.tagName,id:x.id,cls:x.className,width:x.getBoundingClientRect().width,css:getComputedStyle(x).width}))}));out.push({url,status:r.status(),...d});console.log(JSON.stringify(out.at(-1)));}catch(e){out.push({url,width:w,error:e.message});}await p.close();}}await b.close();fs.mkdirSync('qa-report',{recursive:true});fs.writeFileSync('qa-report/result.json',JSON.stringify(out,null,2));})();